private List<Map<String,Object>> checkAxleEnvelope(String sectionId, String trainNo, List<Integer> weights, SectionLimitProfile limits) {
    List<Map<String,Object>> violations = new ArrayList<>();
    for (int i = 0; i < weights.size(); i++) {
        long w = weights.get(i);
        if (w > limits.singleAxleLimitKg()) {
            detail {type:SINGLE_AXLE_EXCEEDED, sectionId, trainNo, axleIndex:i, weightKg:w, limitKg}
        }
    }
    for (int i = 0; i + 2 < weights.size(); i++) {
        long sum = Math.addExact(Math.addExact((long)weights.get(i), weights.get(i+1)), weights.get(i+2));
        if (sum > limits.window3LimitKg()) {
            detail {type:WINDOW3_EXCEEDED, sectionId, trainNo, windowStart:i, sumKg:sum, limitKg}
        }
    }
    return violations;
}
